def cta(): return '<section class="cta wrap"><div><span class="eyebrow">EL SIGUIENTE PASO</span><h2>Hablemos de tu salud.</h2><p>Una consulta para entender tu caso y resolver tus dudas.</p></div><a class="button light" href="/contacto/">Solicitar una consulta</a></section>'
